add_action( 'woocommerce_after_quantity_input_field', 'perfectpixel_quantity_unit_suffix' );

function perfectpixel_quantity_unit_suffix() {
	global $product;
	if ( ! is_product() || ! $product ) {
		return;
	}
	$product_ids  = wp_parse_id_list( '{{qty_suffix_product_ids}}' );
	$category_ids = wp_parse_id_list( '{{qty_suffix_category_ids}}' );
	$id           = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();

	$applies = ! $product_ids && ! $category_ids;
	if ( $product_ids && in_array( $id, $product_ids, true ) ) {
		$applies = true;
	}
	if ( $category_ids && has_term( $category_ids, 'product_cat', $id ) ) {
		$applies = true;
	}
	if ( $applies ) {
		echo '<span class="perfectpixel-qty-suffix" style="margin:0 .75em 0 .4em;align-self:center">' . esc_html( '{{qty_suffix_text}}' ) . '</span>';
	}
}
